      ? { raw: draft, render: (text, trimmed) => quote(text) + (trimmed ? '\n<i>Recortado para Telegram. El correo sale entero.</i>' : '') }
      : '(vacío: escribe tú la respuesta con Editar)');
  }
  parts.push('', '<b>Fuentes</b>', escapeHtml(formatSources(row.sources)));
