  const shown = ref || 'sin número';
  const issue = /^https:\/\/[^\s"<>]+$/.test(url) ? `<a href="${escapeAttr(url)}">${shown}</a>` : shown;
  const parts = ['🐞 <b>Bug registrado</b>', fromLine(row), `Issue: ${issue}`];
