  parts.push(draft
    ? { raw: draft, render: (text, trimmed) => quote(text) + (trimmed ? '\n<i>Recortada para Telegram.</i>' : '') }
    : '(sin borrador)');
  parts.push('', 'No se ha contestado: escríbele tú.');
  return fit(parts);
}

